Cypher query: MATCH (n:__Entity__)-[r]-(m:__Entity__)
WHERE (
  toLower(n.name) CONTAINS 'turkish' OR any(alias IN coalesce(n.aliases, []) WHERE toLower(alias) CONTAINS 'turkish') OR
  toLower(n.name) CONTAINS 'finnish' OR any(alias IN coalesce(n.aliases, []) WHERE toLower(alias) CONTAINS 'finnish') OR
  toLower(n.name) CONTAINS 'hungarian' OR any(alias IN coalesce(n.aliases, []) WHERE toLower(alias) CONTAINS 'hungarian')
)
AND (
  toLower(m.name) CONTAINS 'uralic' OR any(alias IN coalesce(m.aliases, []) WHERE toLower(alias) CONTAINS 'uralic')
)
RETURN n.name AS language, type(r) AS relationship, m.name AS language_family
LIMIT 10
