WHERE (toLower(o.name) CONTAINS 'vice president' OR any(alias IN coalesce(o.aliases, []) WHERE toLower(alias) CONTAINS 'vice president'))
  AND (toLower(o.name) CONTAINS 'united states' OR any(alias IN coalesce(o.aliases, []) WHERE toLower(alias) CONTAINS 'united states') OR toLower(coalesce(r.context, '')) CONTAINS 'united states' OR toLower(coalesce(r.fact, '')) CONTAINS 'united states')
RETURN p.name AS person, p.birth_date AS birth_date, p.age AS age, type(r) AS relationship, coalesce(r.role, r.context, r.relationship, r.relation, r.fact) AS connection, o.name AS office
LIMIT 10
