Cypher query: MATCH (mac:__Entity__)-[appleRel]-(apple:__Entity__)
MATCH (mac)-[releaseRel]-(release:__Entity__)
WHERE (toLower(mac.name) CONTAINS 'macos' OR any(alias IN coalesce(mac.aliases, []) WHERE toLower(alias) CONTAINS 'macos'))
  AND (toLower(apple.name) CONTAINS 'apple' OR any(alias IN coalesce(apple.aliases, []) WHERE toLower(alias) CONTAINS 'apple'))
  AND release.date IS NOT NULL
RETURN release.name AS release, release.date AS release_date, type(releaseRel) AS release_relationship, apple.name AS organization, type(appleRel) AS organization_relationship
ORDER BY release.date DESC
LIMIT 10
